commands:
make check 2>&1 | tail -n 6; make lint 2>&1 | tail -n 1; echo "--- long lines"; awk 'length > 60 {print FILENAME": "FNR": "length}' rosterkit/notices.py tests/test_notices.py; echo "--- double blanks"; awk 'prev=="" && $0=="" {print FILENAME": "FNR} {prev=$0}' rosterkit/notices.py tests/test_notices.py; echo "--- function spans"; python3 -c '
import ast, sys
for path in sys.argv[1:]:
    tree = ast.parse(open(path).read())
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            span = node.end_lineno - node.lineno + 1
            print(path, node.name, span)
' rosterkit/notices.py tests/test_notices.py; echo "--- imports"; sed -n 3,7p rosterkit/notices.py; sed -n 2,5p tests/test_notices.py

make check 2>&1 | tail -n 4; make lint 2>&1 | tail -n 1; echo "--- long lines"; awk 'length > 60 {print FILENAME": "FNR": "length}' rosterkit/notices.py tests/test_notices.py; echo "--- double blanks"; awk 'prev=="" && $0=="" {print FILENAME": "FNR} {prev=$0}' rosterkit/notices.py tests/test_notices.py; echo "--- function spans"; python3 -c '
import ast, sys
for path in sys.argv[1:]:
    tree = ast.parse(open(path).read())
    for node in ast.walk(tree):
        if isinstance(node, ast.FunctionDef):
            print(path, node.name, node.end_lineno - node.lineno + 1)
' rosterkit/notices.py tests/test_notices.py; echo "--- short names"; grep -nE '(for|as) [a-z_]{1,3}\b|\b[a-z_]{1,3} = ' rosterkit/notices.py tests/test_notices.py; echo "--- contractions and digits check on new code"; grep -nE "'" rosterkit/notices.py | head; echo ok

